        )
        .unwrap();
        let m = read_python_membership(dir.path());
        assert!(m.admits(Path::new("packages/kept-example"), false));
        assert!(!m.admits(Path::new("packages/examples/demo"), false));
        assert!(!m.admits(Path::new("tools/outside"), false));
    }

    #[test]
    fn read_python_membership_admits_all_when_workspace_table_absent_but_file_exists() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("pyproject.toml"),
            "[project]\nname = \"solo\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();
        let m = read_python_membership(dir.path());
        assert!(m.admits(Path::new("packages/anything"), false));
    }

    #[test]
    fn read_python_membership_falls_back_to_absent_when_root_toml_is_unparseable() {
        let dir = tempdir().unwrap();
        std::fs::write(dir.path().join("pyproject.toml"), "[tool.uv.workspace\nmembers = [\n").unwrap();
        let m = read_python_membership(dir.path());
        assert!(m.admits(Path::new("packages/anything"), false));
    }

    #[test]
    fn read_python_membership_detects_hybrid_root_and_exempts_it_from_exclude() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("pyproject.toml"),
            "[project]\nname = \"root-pkg\"\nversion = \"0.1.0\"\n\n[tool.uv.workspace]\nmembers = [\"packages/*\"]\nexclude = [\".\"]\n",
        )
        .unwrap();
        let m = read_python_membership(dir.path());
        assert!(m.admits(Path::new("."), true));
    }
}

item.formatted_output:
# Default recipe: fast local CI pipeline (no coverage) via moon & just.
# Use `just ci` explicitly for full CI parity including coverage.
default: ci-fast

# Build debug workspace binaries via moon
build:
    moon run :build

# Build release CLI binary
build-release:
    cargo build --release -p callisto-cli

# Run unit, integration, doctests, and E2E tests. This intentionally uses the
# same Nextest command as CI: a runner/configuration failure must never be
# mistaken for a passing Moon fallback.
test:
    cargo nextest run --workspace --all-features
    cargo test --doc --all-features

# Explicit compatibility path for contributors who do not have cargo-nextest
# installed. It is never used by CI or pre-merge verification.
test-moon:
    moon run :test
    cargo test --doc --all-features

# Exercise the Release-PR action's real shell block with Git and GitHub API
# boundaries faked. This proves the script's control flow given a decision
# shape; it does not call the real `callisto` binary, so it cannot catch a
# mismatch between what Callisto actually serializes and what this script's
# jq expressions expect. See test-release-action-binary for that check.
test-release-action:
    bash .github/actions/callisto-action/tests/test_release_pr_contract.sh

# Compiles callisto and runs the Release-PR action's jq extraction against
# its real JSON output. Requires pending changesets to exercise update and
# supersede decisions; skips cleanly otherwise.
test-release-action-binary:
    bash .github/actions/callisto-action/tests/test_release_pr_decide_binary_contract.sh

# CI variant of `test`: emits Nextest's JUnit report under target/nextest/ci
# for the trusted PR reporter. Keep the everyday local command artifact-free.
test-ci:
    cargo nextest run --workspace --all-features --profile ci
    cargo test --doc --all-features

# Run Clippy lints (warnings treated as errors) as a single workspace invocation.
# Moon's per-project `cargo clippy -p $project` tasks all lock the same shared
# target/ dir, so running them one-per-project serializes on Cargo's own build
# lock instead of parallelizing — a single --workspace invocation lets Cargo's
# internal job scheduler parallelize across crates instead.
lint:
    cargo clippy --workspace --all-targets -- -D warnings

# Lint only projects affected by changes since the base branch. Uses moon's
# project graph to find affected crates, then lints them in one cargo
# invocation (not moon's per-project fan-out) to avoid Cargo's build-lock
# serialization while still skipping unaffected crates entirely.
lint-affected:
    #!/usr/bin/env bash
    set -euo pipefail
    projects=$(moon query projects --affected 2>/dev/null | jq -r '.projects[].id')
    if [ -z "$projects" ]; then
        echo "No projects affected — skipping lint."
        exit 0
    fi
    args=()
    for p in $projects; do args+=(-p "$p"); done
    cargo clippy "${args[@]}" --all-targets -- -D warnings

# Check code formatting compliance via moon
fmt-check:
    moon run :format-check

# Format code automatically via moon
fmt:
    moon run :format

# Security advisory & license check via moon / cargo-deny
audit:
    moon run :audit

# Run mutation testing sweep via cargo-mutants
mutants:
    cargo mutants --workspace

# Run unused dependency check via cargo-machete
machete:
    cargo machete

# Verify public Rust API SemVer breaking changes
check-api:
    cargo semver-checks check-release

# Run structure-aware fuzzing target
fuzz target="parse_package_id":
    cargo fuzz run {{target}}

# Documentation build check (warnings treated as errors)
doc-check:
    RUSTDOCFLAGS="-D warnings" cargo doc --no-deps --workspace

# Verify Moon WASM plugin cross-compilation target and build the real
# cdylib. The black-box Extism/wasmtime sandbox test (tests/moon_wasm_sandbox.rs)
# is NOT re-run here: `just test`'s workspace-wide nextest run already builds
# and executes it (moon_pdk_test_utils is an unconditional dev-dependency, not
# gated by the `pdk` feature), so running it again via `cargo test` here would
# be a third full execution of the same suite once `coverage` runs it a second
# time under instrumentation -- pure redundant runtime, not extra coverage.
wasm-check:
    rustup target add wasm32-wasip1 2>/dev/null || true
    cargo check -p callisto-moon --target wasm32-wasip1 --features pdk
    cargo rustc -p callisto-moon --lib --target wasm32-wasip1 --features pdk --crate-type cdylib

# Generate code coverage report via cargo-llvm-cov. `_pdk.rs`-suffixed files
# are excluded: they contain code that only executes inside a real
# wasm32-wasip1 Extism host (see e.g. crates/callisto-moon/src/runner_pdk.rs's
# module doc comment) -- black-box tested via tests/moon_wasm_sandbox.rs, but
# invisible to native coverage instrumentation by construction, not a real
# testing gap. Any file matching this naming convention is understood to
# document its own exclusion this way.
#
# Optional `threshold`: when set, fails if total line coverage drops below
# it (--fail-under-lines). The human-readable summary is always emitted
# before enforcing the threshold: LCOV output itself contains no aggregate
# percentage, and a failed CI gate must say what developers need to improve.
# Unset locally (informational only, matching ARCHITECTURE.md's "coverage
# generation is a CI-only gate" note); CI calls `just coverage 90` -- this is
# the one command both run, so a CI coverage failure always reproduces locally
# with the exact same invocation.
coverage threshold="":
    #!/usr/bin/env bash
    set -euo pipefail
    args=(--all-features --lcov --output-path lcov.info --ignore-filename-regex '_pdk\.rs$')
    cargo llvm-cov "${args[@]}"
    cargo llvm-cov report --summary-only --ignore-filename-regex '_pdk\.rs$'
    if [[ -n "{{threshold}}" ]]; then
      cargo llvm-cov report --summary-only --ignore-filename-regex '_pdk\.rs$' --fail-under-lines "{{threshold}}"
    fi

# Check per-crate line coverage against a threshold (default 90%). The
# workspace-total --fail-under-lines gate can pass while a small crate is
# far below threshold, since a few large crates dominate the total line
# count -- this catches that case. Requires profile data from a prior
# `cargo llvm-cov` run in this session (e.g. `just coverage` just ran, or
# CI's own coverage step ran first); does not re-run tests itself.
coverage-per-crate threshold="90":
    #!/usr/bin/env bash
    set -euo pipefail
    cargo llvm-cov report --json --summary-only --ignore-filename-regex '_pdk\.rs$' > /tmp/callisto-cov-summary.json
    report=$(jq -r '
        .data[0].files[]
        | select(.filename | test("/crates/"))
        | {crate: (.filename | capture("/crates/(?<c>[^/]+)/").c), count: .summary.lines.count, covered: .summary.lines.covered}
        | [.crate, .count, .covered]
        | @tsv
      ' /tmp/callisto-cov-summary.json \
      | awk -F'\t' -v threshold="{{threshold}}" '
          {sum[$1]+=$2; cov[$1]+=$3}
          END {
            for (c in sum) {
              pct = (cov[c]/sum[c]*100)
              status = (pct+0 < threshold+0) ? "FAIL" : "pass"
              printf "%s\t%d\t%d\t%.2f\t%s\n", c, sum[c], cov[c], pct, status
            }
          }
        ' | sort)
    echo "$report" | awk -F'\t' '{printf "%-25s lines=%-6s covered=%-6s cover=%6s%%  %s\n", $1, $2, $3, $4, $5}'
    echo "$report" | grep -q FAIL && exit 1 || exit 0

# Clean build targets, Moon task caches, and generated artifacts
clean:
    moon clean 2>/dev/null || true
    cargo clean
    rm -f lcov.info callisto-schema.json

# Fast pre-commit hook validation (<500ms formatting check)
pre-commit: fmt-check

# Pre-push hook validation: formatting check plus clippy on affected projects only
pre-push: fmt-check lint-affected

# Install native Git pre-commit and pre-push hooks
hooks:
    @echo '#!/bin/sh\njust pre-commit' > .git/hooks/pre-commit
    @chmod +x .git/hooks/pre-commit
    @echo '#!/bin/sh\njust pre-push' > .git/hooks/pre-push
    @chmod +x .git/hooks/pre-push
    @echo "Git pre-commit and pre-push hooks installed successfully."

# Run full local CI verification pipeline via moon and just
ci: fmt-check lint test audit doc-check wasm-check coverage

# Same as `ci`, minus `coverage`. Real CI (callisto-ci.yml) already runs
# coverage as its own parallel job on a separate runner; locally it's a
# third full-workspace recompile under llvm-cov instrumentation tacked onto
# the end of a serial pipeline. Use this for everyday pre-PR checks;
# coverage numbers are a reporting concern, not something every local run
# needs to regenerate.
ci-fast: fmt-check lint test audit doc-check wasm-check
name: 'Setup Callisto WASM'
description: 'Pre-downloads and caches callisto-moon.wasm from GitHub Releases for Moon integration'
inputs:
  version:
    description: 'Callisto WASM version to download (defaults to "latest")'
    required: false
    default: 'latest'
  dest:
    description: 'Destination path for callisto-moon.wasm'
    required: false
    default: '.moon/cache/ext/callisto-moon.wasm'

outputs:
  path:
    description: 'Path to the local cached callisto-moon.wasm file'
    value: ${{ steps.download-wasm.outputs.path || inputs.dest }}

runs:
  using: 'composite'
  steps:
    - name: Cache Callisto WASM
      id: cache-wasm
      # actions/cache v4.2.3
      uses: actions/cache@5a3ec84eff668545956fd18022155c47e93e2684
      with:
        path: ${{ inputs.dest }}
        key: ${{ runner.os }}-callisto-wasm-${{ inputs.version }}

    - name: Download Callisto WASM Plugin
      id: download-wasm
      if: steps.cache-wasm.outputs.cache-hit != 'true'
      shell: bash
      env:
        INPUT_WASM_DEST: ${{ inputs.dest }}
        INPUT_WASM_VERSION: ${{ inputs.version }}
      run: |
        DEST_PATH="$INPUT_WASM_DEST"
        mkdir -p "$(dirname "$DEST_PATH")"
        TAG_NAME="$INPUT_WASM_VERSION"

        if [[ "$TAG_NAME" == "latest" ]]; then
          DOWNLOAD_URL="https://github.com/orin-dx/callisto/releases/latest/download/callisto-moon.wasm"
        else
          DOWNLOAD_URL="https://github.com/orin-dx/callisto/releases/download/${TAG_NAME}/callisto-moon.wasm"
        fi

        echo "Downloading Callisto WASM plugin from $DOWNLOAD_URL to $DEST_PATH..."
        if ! curl -sL -f "$DOWNLOAD_URL" -o "$DEST_PATH"; then
          echo "Release binary asset not found. Compiling Callisto WASM plugin locally..."
          rustup target add wasm32-wasip1 2>/dev/null || true
          cargo build -p callisto-moon --target wasm32-wasip1 --features pdk --release
          cp target/wasm32-wasip1/release/callisto_moon.wasm "$DEST_PATH"
        fi

        echo "path=$DEST_PATH" >> $GITHUB_OUTPUT
use callisto_model::ManifestFormat;
use globset::{GlobBuilder, GlobSet, GlobSetBuilder};
use std::path::Path;

/// A [`GlobSet`] pair implementing npm/pnpm/Yarn-style workspace glob
/// negation. `globset`'s `GlobSetBuilder` has no negation concept of its
/// own -- a pattern with a leading `!` is just another literal
/// positive-match glob to it, so `!packages/excluded` compiles into a glob
/// that matches paths literally starting with the character `!`, which
/// never matches any real path. That silently no-ops the negation instead
/// of excluding anything.
///
/// A path is admitted only when it matches at least one `positive` pattern
/// and matches none of the `negative` (`!`-stripped) patterns -- mirroring
/// how npm/pnpm/Yarn actually resolve workspace globs (later patterns can
/// negate earlier ones; a leading `!` excludes). A positive-only pattern
/// list behaves exactly as a plain [`GlobSet`] would. An all-negative list
/// has an empty positive set, so `is_match` is always `false` -- there is no
/// positive baseline for the negation to carve an exclusion out of.
pub(crate) struct NegatableGlobSet {
    positive: GlobSet,
    negative: GlobSet,
}

impl NegatableGlobSet {
    pub(crate) fn is_match(&self, path: &Path) -> bool {
        self.positive.is_match(path) && !self.negative.is_match(path)
    }

    pub(crate) fn empty() -> Self {
        NegatableGlobSet {
            positive: GlobSet::empty(),
            negative: GlobSet::empty(),
        }
    }
}

/// Builds a [`NegatableGlobSet`] from a list of glob strings, matched with
/// `literal_separator(true)` semantics (`*` does not cross `/`; `**` does)
/// against forward-slash-normalized, workspace-relative paths. An entry
/// with a leading `!` is treated as a negative (exclusion) pattern -- see
/// [`NegatableGlobSet`].
///
/// Per-entry glob-compile-failure rule: an entry that fails to compile is
/// skipped and treated as never-matching; every other syntactically valid
/// entry in the same list is still compiled and matched normally. Never
/// panics, never returns an error.
pub(crate) fn build_globset(entries: &[String]) -> NegatableGlobSet {
    let mut positive = GlobSetBuilder::new();
    let mut negative = GlobSetBuilder::new();
    for entry in entries {
        let (builder, pattern) = match entry.strip_prefix('!') {
            Some(rest) => (&mut negative, rest),
            None => (&mut positive, entry.as_str()),
        };
        if let Ok(glob) = GlobBuilder::new(pattern).literal_separator(true).build() {
            builder.add(glob);
        }
    }
    NegatableGlobSet {
        positive: positive.build().unwrap_or_else(|_| GlobSet::empty()),
        negative: negative.build().unwrap_or_else(|_| GlobSet::empty()),
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn yaml_rust2_smoke_test_parses_a_trivial_mapping() {
        let docs = yaml_rust2::YamlLoader::load_from_str("packages:\n  - \"a\"\n").unwrap();
        assert_eq!(docs.len(), 1);
    }
}

/// Workspace-membership filter shared by Cargo's `[workspace]` and uv's
/// `[tool.uv.workspace]` -- both use the identical members/exclude
/// glob-array shape, including a root manifest that is itself both a
/// package/project and a workspace root (hybrid root). `NpmMembership`
/// deliberately does NOT go through this type: npm's shape genuinely
/// differs (JSON not TOML, no `exclude` concept, and a pnpm-workspace.yaml
/// fallback with its own precedence rules).
pub(crate) struct Membership {
    members: Option<NegatableGlobSet>,
    exclude: NegatableGlobSet,
    hybrid_root: bool,
}

impl Membership {
    /// `rel` must be a workspace-relative, forward-slash-normalized path.
    /// `is_root` is true exactly when `rel == Path::new(".")`.
    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
        if is_root && self.hybrid_root {
            return true;
        }
        if self.exclude.is_match(rel) {
            return false;
        }
        match &self.members {
            None => true,
            Some(members) => members.is_match(rel),
        }
    }

    fn absent() -> Self {
        Membership {
            members: None,
            exclude: NegatableGlobSet::empty(),
            hybrid_root: false,
        }
    }
}

/// Safely parses a TOML array-of-strings item, returning `None` for any
/// other shape (bare string, table, non-string entries, etc.) instead of
/// panicking.
fn parse_toml_string_array(item: &toml_edit::Item) -> Option<Vec<String>> {
    let arr = item.as_array()?;
    let mut out = Vec::with_capacity(arr.len());
    for v in arr.iter() {
        out.push(v.as_str()?.to_string());
    }
    Some(out)
}

/// Describes where an ecosystem's workspace-membership table lives inside
/// its root manifest, so [`read_membership`] can walk to it generically
/// instead of each ecosystem hand-rolling the same members/exclude/
/// hybrid-root logic around a different table path.
pub(crate) struct MembershipSpec {
    /// The root manifest's file name, e.g. `Cargo.toml`.
    manifest_file_name: &'static str,
    /// Nested table keys leading to the workspace table, walked in order
    /// from the document root, e.g. `["workspace"]` for Cargo or
    /// `["tool", "uv", "workspace"]` for uv-based Python.
    table_path: &'static [&'static str],
    /// Top-level key whose co-presence with the workspace table marks a
    /// hybrid root, e.g. `"package"` for Cargo or `"project"` for Python.
    owner_key: &'static str,
}

pub(crate) const CARGO_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
    manifest_file_name: ManifestFormat::CargoToml.file_name(),
    table_path: &["workspace"],
    owner_key: "package",
};

pub(crate) const PYTHON_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
    manifest_file_name: ManifestFormat::PyprojectToml.file_name(),
    table_path: &["tool", "uv", "workspace"],
    owner_key: "project",
};

/// NAIVE first pass: only handles (1) the manifest file entirely absent, and
/// (2) a well-formed workspace table with members/exclude arrays of
/// strings. Every other shape (workspace table absent, TOML unparseable,
/// members/exclude present but not an array-of-strings, members key
/// absent) falls back to an absent-filter (admit-all) result -- see the
/// `cargo_membership_tests`/`python_membership_tests` modules for the
/// exact fallback matrix this is pinned against.
pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Membership {
    let content = match std::fs::read_to_string(root.join(spec.manifest_file_name)) {
        Ok(c) => c,
        Err(_) => return Membership::absent(),
    };
    let doc = match content.parse::<toml_edit::DocumentMut>() {
        Ok(d) => d,
        Err(_) => return Membership::absent(),
    };

    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
    for key in &spec.table_path[1..] {
        cursor = cursor.and_then(|c| c.get(*key));
    }

    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
    let Some(workspace) = cursor else {
        return Membership {
            members: None,
            exclude: NegatableGlobSet::empty(),
            hybrid_root,
        };
    };
    let members = workspace
        .get("members")
        .and_then(parse_toml_string_array)
        .map(|v| build_globset(&v));
    let exclude = workspace
        .get("exclude")
        .and_then(parse_toml_string_array)
        .map(|v| build_globset(&v))
        .unwrap_or_else(NegatableGlobSet::empty);
    Membership {
        members,
        exclude,
        hybrid_root,
    }
}

pub(crate) fn read_cargo_membership(root: &Path) -> Membership {
    read_membership(root, &CARGO_MEMBERSHIP_SPEC)
}

pub(crate) fn read_python_membership(root: &Path) -> Membership {
    read_membership(root, &PYTHON_MEMBERSHIP_SPEC)
}

#[cfg(test)]
mod cargo_membership_tests {
    use super::*;
    use std::path::Path;
    use tempfile::tempdir;

    #[test]
    fn read_cargo_membership_admits_all_when_no_cargo_toml_file_exists() {
        let dir = tempdir().unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("crates/anything"), false));
    }

    #[test]
    fn read_cargo_membership_honors_well_formed_members_and_exclude() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[workspace]\nmembers = [\"crates/*\"]\nexclude = [\"crates/scratch-example\"]\n",
        )
        .unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("crates/kept-example"), false));
        assert!(!m.admits(Path::new("crates/scratch-example"), false));
        assert!(!m.admits(Path::new("tools/outside"), false));
    }

    #[test]
    fn read_cargo_membership_falls_back_to_absent_when_members_is_bare_string() {
        let dir = tempdir().unwrap();
        std::fs::write(dir.path().join("Cargo.toml"), "[workspace]\nmembers = \"crates/*\"\n").unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("tools/outside"), false));
    }

    #[test]
    fn read_cargo_membership_falls_back_to_excluding_nothing_when_exclude_is_bare_string() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[workspace]\nmembers = [\"crates/*\"]\nexclude = \"crates/scratch-example\"\n",
        )
        .unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("crates/scratch-example"), false));
        assert!(!m.admits(Path::new("tools/outside"), false));
    }

    #[test]
    fn read_cargo_membership_detects_hybrid_root_and_exempts_it_from_exclude() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"root-crate\"\nversion = \"0.1.0\"\n\n[workspace]\nmembers = [\"crates/*\"]\nexclude = [\".\"]\n",
        )
        .unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("."), true));
    }

    #[test]
    fn read_cargo_membership_admits_all_when_workspace_table_absent_but_file_exists() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[package]\nname = \"solo\"\nversion = \"0.1.0\"\n",
        )
        .unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("crates/anything"), false));
    }

    #[test]
    fn read_cargo_membership_falls_back_to_absent_when_root_toml_is_unparseable() {
        let dir = tempdir().unwrap();
        std::fs::write(dir.path().join("Cargo.toml"), "[workspace\nmembers = [\n").unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("crates/anything"), false));
    }

    #[test]
    fn read_cargo_membership_honors_exclude_when_no_members_key_present() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[workspace]\nexclude = [\"crates/foo\"]\n",
        )
        .unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(!m.admits(Path::new("crates/foo"), false));
        assert!(m.admits(Path::new("crates/kept"), false));
    }

    #[test]
    fn read_cargo_membership_members_array_honors_negated_pattern() {
        let dir = tempdir().unwrap();
        std::fs::write(
            dir.path().join("Cargo.toml"),
            "[workspace]\nmembers = [\"crates/*\", \"!crates/excluded-one\"]\n",
        )
        .unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(m.admits(Path::new("crates/kept"), false));
        assert!(!m.admits(Path::new("crates/excluded-one"), false));
    }

    #[test]
    fn read_cargo_membership_empty_members_array_admits_nothing() {
        let dir = tempdir().unwrap();
        std::fs::write(dir.path().join("Cargo.toml"), "[workspace]\nmembers = []\n").unwrap();
        let m = read_cargo_membership(dir.path());
        assert!(!m.admits(Path::new("crates/anything"), false));
    }
}

pub(crate) struct NpmMembership {
    globs: Option<NegatableGlobSet>,
    hybrid_root: bool,
}

impl NpmMembership {
    /// `rel` must be a workspace-relative, forward-slash-normalized path.
    /// `is_root` is true exactly when `rel == Path::new(".")`.
    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
        if is_root && self.hybrid_root {
            return true;
        }
        match &self.globs {
            None => true,
            Some(globs) => globs.is_match(rel),
        }
    }
}

/// True when the root package.json exists, parses as JSON, and declares a
/// "name" field. Independent of which arm (package.json "workspaces" or a
/// sibling pnpm-workspace.yaml) governs the rest of npm membership -- see
/// AC-16/AC-16b/AC-17/AC-10d.
fn package_json_declares_name(root: &Path) -> bool {
    let Ok(content) = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())) else {
        return false;
    };
    let Ok(val) = serde_json::from_str::<serde_json::Value>(&content) else {
        return false;
    };
    val.get("name").is_some()
}

pub(crate) fn read_npm_membership(root: &Path) -> NpmMembership {
    let hybrid_root = package_json_declares_name(root);
    if let Some(packages) = read_pnpm_packages(root) {
        return NpmMembership {
            globs: Some(build_globset(&packages)),
            hybrid_root,
        };
    }
    NpmMembership {
        globs: read_package_json_workspaces(root).map(|v| build_globset(&v)),
        hybrid_root,
    }
}

/// YAML-parse-Err, zero-documents, packages-key-missing-or-wrong-shape, and
/// a non-string sequence element all safely fall back to `None` (which
/// causes `read_npm_membership` to fall through to
/// `read_package_json_workspaces` or admit-all).
fn read_pnpm_packages(root: &Path) -> Option<Vec<String>> {
    let content = std::fs::read_to_string(root.join("pnpm-workspace.yaml")).ok()?;
    let docs = yaml_rust2::YamlLoader::load_from_str(&content).ok()?;
    let doc = docs.first()?;
    let packages = doc["packages"].as_vec()?;
    let mut out = Vec::with_capacity(packages.len());
    for item in packages {
        out.push(item.as_str()?.to_string());
    }
    Some(out)
}

/// File-absent, field-absent, non-array "workspaces", and non-string array
/// entries all safely fall back to `None` (a plain `?`-chain), which causes
/// `read_npm_membership` to admit-all.
fn read_package_json_workspaces(root: &Path) -> Option<Vec<String>> {
    let content = std::fs::read_to_string(root.join(ManifestFormat::PackageJson.file_name())).ok()?;
    let val: serde_json::Value = serde_json::from_str(&content).ok()?;
    let field = val.get("workspaces")?;
    let arr = field.as_array()?;
    let mut out = Vec::with_capacity(arr.len());
    for v in arr {
        out.push(v.as_str()?.to_string());
    }
    Some(out)
}

